-- Run once on an EMPTY Supabase project: SQL Editor -> New query -> paste -> Run.
begin;

-- ===== supabase/migrations/20261023000001_extensions_and_types.sql =====
-- ROYAL INK commerce platform — base extensions, enums and shared helpers.
-- Target: Supabase (PostgreSQL 15+). Apply in filename order on an empty database
-- (supabase db push); they are not written to be re-run.

-- Supabase keeps extensions in the "extensions" schema (already on its search_path).
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists unaccent with schema extensions;
create extension if not exists citext with schema extensions;

-- ---------------------------------------------------------------------------
-- Enumerations
-- ---------------------------------------------------------------------------
create type product_type as enum (
  'ink_bottle', 'ink_cartridge', 'toner', 'printer', 'drum', 'maintenance_box',
  'printer_part', 'paper', 'label', 'cleaning', 'other'
);
create type product_status as enum ('draft', 'active', 'archived');
create type product_origin as enum ('original', 'compatible');
create type yield_type as enum ('standard', 'high', 'extra_high');
create type ink_color as enum (
  'black', 'cyan', 'magenta', 'yellow', 'photo_black', 'matte_black', 'grey',
  'light_cyan', 'light_magenta', 'red', 'blue', 'green', 'white', 'tri_color', 'multi', 'none'
);
create type printer_kind as enum ('inkjet', 'laser', 'multifunction', 'tank', 'office', 'home', 'large_format', 'other');
create type user_role as enum ('customer', 'staff', 'admin');
create type business_status as enum ('pending', 'approved', 'rejected');
create type delivery_method as enum ('home', 'pickup');
create type payment_method as enum ('cash_on_delivery');  -- extend only once a real provider is configured
create type payment_status as enum ('unpaid', 'paid', 'refunded');
create type order_status as enum (
  'pending', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled', 'returned'
);
create type stock_reason as enum ('initial', 'purchase', 'sale', 'adjustment', 'return', 'cancellation', 'damage');
create type promo_kind as enum ('percent', 'fixed', 'free_shipping');
create type quote_status as enum ('new', 'in_review', 'quoted', 'accepted', 'rejected', 'expired');
create type return_status as enum ('requested', 'approved', 'rejected', 'received', 'refunded');
create type review_status as enum ('pending', 'approved', 'rejected');

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

-- Localised text is stored as {"ar": "...", "fr": "...", "en": "..."}.
create or replace function is_localized(j jsonb) returns boolean
language sql immutable as $$
  select j is not null
     and jsonb_typeof(j) = 'object'
     and (select bool_and(k in ('ar', 'fr', 'en')) from jsonb_object_keys(j) k)
     and coalesce(nullif(j->>'fr', ''), nullif(j->>'en', ''), nullif(j->>'ar', '')) is not null
$$;

-- Lower-case, accent-free text used for search.
create or replace function search_normalize(t text) returns text
language sql immutable parallel safe as $$
  select lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(t, '')))
$$;

-- Product codes compare without punctuation: "TN-2420", "tn2420" and "TN 2420" all match.
create or replace function code_normalize(t text) returns text
language sql immutable parallel safe as $$
  select regexp_replace(lower(coalesce(t, '')), '[^a-z0-9]', '', 'g')
$$;

create or replace function touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ===== supabase/migrations/20261023000002_catalog.sql =====
-- Catalog: categories, brands, products, images, inventory, volume pricing.

create table categories (
  id          uuid primary key default gen_random_uuid(),
  parent_id   uuid references categories(id) on delete restrict,
  slug        text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name        jsonb not null check (is_localized(name)),
  description jsonb check (description is null or is_localized(description)),
  image_path  text,
  sort_order  int not null default 0,
  is_active   boolean not null default true,
  seo         jsonb not null default '{}',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index on categories (parent_id);

create table brands (
  id               uuid primary key default gen_random_uuid(),
  slug             text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name             text not null,
  logo_path        text,
  makes_printers   boolean not null default false,  -- shown in "Find your ink"
  is_active        boolean not null default true,
  sort_order       int not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- Optional grouping so colour / yield variants of one family link to each other.
create table product_groups (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique,
  name       jsonb not null check (is_localized(name)),
  created_at timestamptz not null default now()
);

create table products (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  sku             text not null unique,
  product_type    product_type not null,
  category_id     uuid not null references categories(id) on delete restrict,
  brand_id        uuid references brands(id) on delete restrict,
  group_id        uuid references product_groups(id) on delete set null,
  variant_label   jsonb check (variant_label is null or is_localized(variant_label)),
  name            jsonb not null check (is_localized(name)),
  short_description jsonb check (short_description is null or is_localized(short_description)),
  description     jsonb check (description is null or is_localized(description)),
  model_code      text,            -- cartridge / toner code, e.g. "057H", "TN-2420"
  oem_reference   text,            -- manufacturer part number, e.g. "3010C002"
  origin          product_origin,  -- original (OEM) or compatible; null for non-consumables
  color           ink_color,
  yield_type      yield_type,
  page_yield      int check (page_yield is null or page_yield > 0),
  volume_ml       numeric(8,2) check (volume_ml is null or volume_ml > 0),
  pack_size       int not null default 1 check (pack_size > 0),
  specs           jsonb not null default '{}',  -- free-form technical specifications
  price_dzd       numeric(12,2) check (price_dzd is null or price_dzd >= 0),  -- null = not sold online yet
  compare_at_dzd  numeric(12,2) check (compare_at_dzd is null or compare_at_dzd >= 0),
  status          product_status not null default 'draft',
  is_featured     boolean not null default false,
  weight_grams    int check (weight_grams is null or weight_grams > 0),
  model_3d_path   text,
  seo             jsonb not null default '{}',
  search_text     text not null default '',   -- maintained by trigger
  code_text       text not null default '',   -- maintained by trigger
  search_vector   tsvector,                   -- maintained by trigger
  published_at    timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  check (status <> 'active' or price_dzd is not null)  -- cannot sell without a real price
);
create index on products (category_id);
create index on products (brand_id);
create index on products (status, product_type);
create index on products (group_id);
create index products_search_vector_idx on products using gin (search_vector);
create index products_search_trgm_idx on products using gin (search_text extensions.gin_trgm_ops);
create index products_code_trgm_idx on products using gin (code_text extensions.gin_trgm_ops);

create table product_images (
  id           uuid primary key default gen_random_uuid(),
  product_id   uuid not null references products(id) on delete cascade,
  storage_path text not null,
  alt          jsonb check (alt is null or is_localized(alt)),
  position     int not null default 0,
  created_at   timestamptz not null default now()
);
create index on product_images (product_id, position);

create table inventory (
  product_id          uuid primary key references products(id) on delete cascade,
  quantity            int not null default 0 check (quantity >= 0),
  low_stock_threshold int not null default 5 check (low_stock_threshold >= 0),
  updated_at          timestamptz not null default now()
);

create table inventory_movements (
  id          bigint generated always as identity primary key,
  product_id  uuid not null references products(id) on delete cascade,
  delta       int not null check (delta <> 0),
  quantity_after int not null,
  reason      stock_reason not null,
  order_id    uuid,              -- FK added in commerce migration
  note        text,
  created_by  uuid,              -- auth user id of the staff member, null for system
  created_at  timestamptz not null default now()
);
create index on inventory_movements (product_id, created_at desc);

-- Volume (B2B) pricing: the lowest applicable tier price wins.
create table price_tiers (
  id            uuid primary key default gen_random_uuid(),
  product_id    uuid not null references products(id) on delete cascade,
  min_quantity  int not null check (min_quantity >= 2),
  price_dzd     numeric(12,2) not null check (price_dzd >= 0),
  business_only boolean not null default true,
  unique (product_id, min_quantity, business_only)
);

-- Every product gets an inventory row.
create or replace function products_after_insert() returns trigger
language plpgsql security definer set search_path = public, extensions as $$
begin
  insert into inventory (product_id) values (new.id) on conflict do nothing;
  return new;
end $$;
create trigger products_inventory after insert on products
  for each row execute function products_after_insert();

-- Keep search columns in sync (names in every language, codes, brand).
create or replace function products_search_refresh() returns trigger
language plpgsql set search_path = public, extensions as $$
declare
  brand_name text;
begin
  select b.name into brand_name from brands b where b.id = new.brand_id;
  new.search_text := search_normalize(concat_ws(' ',
    new.name->>'ar', new.name->>'fr', new.name->>'en',
    new.variant_label->>'fr', new.variant_label->>'en', new.variant_label->>'ar',
    brand_name, new.model_code, new.oem_reference, new.sku));
  new.code_text := concat_ws(' ', code_normalize(new.model_code), code_normalize(new.oem_reference), code_normalize(new.sku));
  new.search_vector :=
       setweight(to_tsvector('simple', search_normalize(concat_ws(' ', new.model_code, new.oem_reference, new.sku))), 'A')
    || setweight(to_tsvector('simple', search_normalize(concat_ws(' ', new.name->>'ar', new.name->>'fr', new.name->>'en', brand_name))), 'B')
    || setweight(to_tsvector('simple', search_normalize(concat_ws(' ', new.short_description->>'fr', new.short_description->>'en', new.short_description->>'ar'))), 'C');
  if new.status = 'active' and new.published_at is null then
    new.published_at := now();
  end if;
  return new;
end $$;
create trigger products_search before insert or update on products
  for each row execute function products_search_refresh();

-- Renaming a brand refreshes its products' search text.
create or replace function brands_after_update() returns trigger
language plpgsql set search_path = public, extensions as $$
begin
  if new.name is distinct from old.name then
    update products set updated_at = now() where brand_id = new.id;
  end if;
  return new;
end $$;
create trigger brands_refresh_products after update on brands
  for each row execute function brands_after_update();

create trigger categories_touch before update on categories for each row execute function touch_updated_at();
create trigger brands_touch before update on brands for each row execute function touch_updated_at();
create trigger products_touch before update on products for each row execute function touch_updated_at();
create trigger inventory_touch before update on inventory for each row execute function touch_updated_at();

-- ===== supabase/migrations/20261023000003_compatibility.sql =====
-- Printer compatibility engine: brand -> series -> model, and a verified
-- many-to-many relation between printers and supply products.

create table printer_series (
  id         uuid primary key default gen_random_uuid(),
  brand_id   uuid not null references brands(id) on delete restrict,
  slug       text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name       text not null,                -- e.g. "i-SENSYS MF440", "EcoTank"
  sort_order int not null default 0,
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  unique (brand_id, slug)
);

create table printers (
  id          uuid primary key default gen_random_uuid(),
  brand_id    uuid not null references brands(id) on delete restrict,
  series_id   uuid references printer_series(id) on delete set null,
  slug        text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  model       text not null,               -- e.g. "i-SENSYS MF443dw"
  kind        printer_kind not null default 'other',
  product_id  uuid unique references products(id) on delete set null,  -- when the printer itself is sold
  is_active   boolean not null default true,
  model_norm  text generated always as (regexp_replace(lower(model), '[^a-z0-9]', '', 'g')) stored,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (brand_id, model)
);
create index on printers (series_id);
create index printers_model_trgm_idx on printers using gin (model_norm extensions.gin_trgm_ops);

-- Only rows with verified = true are ever shown to customers.
create table product_compatibility (
  product_id  uuid not null references products(id) on delete cascade,
  printer_id  uuid not null references printers(id) on delete cascade,
  verified    boolean not null default false,
  source      text,                         -- where the information comes from (OEM datasheet, test, supplier)
  verified_by uuid,                         -- staff auth user id
  verified_at timestamptz,
  created_at  timestamptz not null default now(),
  primary key (product_id, printer_id),
  check (not verified or verified_at is not null)
);
create index on product_compatibility (printer_id) where verified;

create trigger printers_touch before update on printers for each row execute function touch_updated_at();

-- Verified, sellable supplies for one printer.
create or replace view printer_supplies with (security_invoker = true) as
select pc.printer_id, p.*
from product_compatibility pc
join products p on p.id = pc.product_id
where pc.verified and p.status = 'active';

-- Verified printers for one product (reverse lookup on product pages).
create or replace view product_printers with (security_invoker = true) as
select pc.product_id, pr.id as printer_id, pr.slug, pr.model, pr.kind,
       b.id as brand_id, b.name as brand_name, s.id as series_id, s.name as series_name
from product_compatibility pc
join printers pr on pr.id = pc.printer_id and pr.is_active
join brands b on b.id = pr.brand_id
left join printer_series s on s.id = pr.series_id
where pc.verified;

-- ===== supabase/migrations/20261023000004_customers_delivery.sql =====
-- Customers, business accounts, Algerian delivery geography and rates.

create table profiles (
  id           uuid primary key references auth.users(id) on delete cascade,
  full_name    text,
  phone        text,
  role         user_role not null default 'customer',
  locale       text not null default 'ar' check (locale in ('ar', 'fr', 'en')),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create trigger profiles_touch before update on profiles for each row execute function touch_updated_at();

-- Create a profile for every new auth user.
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, new.raw_user_meta_data->>'full_name')
  on conflict do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function handle_new_user();

create table business_accounts (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid not null unique references profiles(id) on delete cascade,
  company_name  text not null,
  activity      text,
  nif           text,   -- Numéro d'identification fiscale
  nis           text,   -- Numéro d'identification statistique
  rc            text,   -- Registre du commerce
  article_imposition text,
  billing_address text,
  status        business_status not null default 'pending',
  reviewed_by   uuid,
  reviewed_at   timestamptz,
  created_at    timestamptz not null default now()
);

-- Wilayas are reference data; new administrative divisions can be added by admins.
create table wilayas (
  code       smallint primary key check (code between 1 and 99),
  name       jsonb not null check (is_localized(name)),
  is_active  boolean not null default true
);

-- Communes are imported from an official source (see docs/DATA.md); none are invented.
create table communes (
  id          serial primary key,
  wilaya_code smallint not null references wilayas(code),
  name        jsonb not null check (is_localized(name)),
  postal_code text,
  is_active   boolean not null default true,
  unique (wilaya_code, postal_code, name)
);
create index on communes (wilaya_code);

create table pickup_points (
  id          uuid primary key default gen_random_uuid(),
  wilaya_code smallint not null references wilayas(code),
  commune_id  int references communes(id),
  name        text not null,
  address     text not null,
  phone       text,
  opening_hours text,
  is_active   boolean not null default true
);

-- No rate row (or is_active = false) means the method is unavailable for that wilaya.
create table delivery_rates (
  wilaya_code  smallint not null references wilayas(code),
  method       delivery_method not null,
  fee_dzd      numeric(10,2) not null check (fee_dzd >= 0),
  free_over_dzd numeric(12,2) check (free_over_dzd is null or free_over_dzd > 0),
  eta_min_days smallint check (eta_min_days is null or eta_min_days >= 0),
  eta_max_days smallint check (eta_max_days is null or eta_max_days >= eta_min_days),
  is_active    boolean not null default true,
  primary key (wilaya_code, method)
);

create table addresses (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references profiles(id) on delete cascade,
  label        text,
  full_name    text not null,
  phone        text not null,
  wilaya_code  smallint not null references wilayas(code),
  commune_id   int references communes(id),
  address_line text not null,
  is_default   boolean not null default false,
  created_at   timestamptz not null default now()
);
create unique index addresses_one_default on addresses (user_id) where is_default;

-- Algerian phone numbers: 0XXXXXXXXX or +213XXXXXXXXX (spaces, dots and dashes ignored).
create or replace function normalize_dz_phone(p text) returns text
language plpgsql immutable as $$
declare
  d text := regexp_replace(coalesce(p, ''), '[\s.\-()]', '', 'g');
begin
  if d ~ '^\+213[1-9][0-9]{7,8}$' then
    return '0' || substr(d, 5);
  elsif d ~ '^00213[1-9][0-9]{7,8}$' then
    return '0' || substr(d, 6);
  elsif d ~ '^0[1-9][0-9]{7,8}$' then
    return d;
  end if;
  return null;
end $$;

-- ===== supabase/migrations/20261023000005_commerce.sql =====
-- Carts, wishlists, promotions, orders, returns, quotations, reviews, marketing.

-- Carts: one per signed-in user, or one per guest token (httpOnly cookie, server-side only).
create table carts (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid unique references profiles(id) on delete cascade,
  guest_token uuid unique,
  updated_at  timestamptz not null default now(),
  check ((user_id is null) <> (guest_token is null))
);

create table cart_items (
  cart_id    uuid not null references carts(id) on delete cascade,
  product_id uuid not null references products(id) on delete cascade,
  quantity   int not null check (quantity between 1 and 999),
  added_at   timestamptz not null default now(),
  primary key (cart_id, product_id)
);

create table wishlist_items (
  user_id    uuid not null references profiles(id) on delete cascade,
  product_id uuid not null references products(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, product_id)
);

create table promo_codes (
  id            uuid primary key default gen_random_uuid(),
  code          extensions.citext not null unique,
  kind          promo_kind not null,
  value         numeric(12,2) not null default 0 check (value >= 0),
  min_subtotal_dzd numeric(12,2) not null default 0,
  max_uses      int check (max_uses is null or max_uses > 0),
  used_count    int not null default 0,
  per_customer_limit int check (per_customer_limit is null or per_customer_limit > 0),
  starts_at     timestamptz,
  ends_at       timestamptz,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  check (kind <> 'percent' or value <= 100)
);

create sequence order_number_seq start 1000;
create sequence invoice_number_seq start 1;

create table orders (
  id              uuid primary key default gen_random_uuid(),
  order_number    text not null unique default ('RI-' || nextval('order_number_seq')),
  user_id         uuid references profiles(id) on delete set null,
  guest_token     uuid,                       -- lets a guest view their own order
  status          order_status not null default 'pending',
  payment_method  payment_method not null default 'cash_on_delivery',
  payment_status  payment_status not null default 'unpaid',
  customer_name   text not null,
  customer_phone  text not null,
  customer_email  text,
  company_name    text,
  delivery_method delivery_method not null,
  wilaya_code     smallint not null references wilayas(code),
  commune_id      int references communes(id),
  address_line    text,
  pickup_point_id uuid references pickup_points(id),
  subtotal_dzd    numeric(12,2) not null,
  discount_dzd    numeric(12,2) not null default 0,
  delivery_fee_dzd numeric(12,2) not null,
  total_dzd       numeric(12,2) not null,
  promo_code_id   uuid references promo_codes(id),
  customer_note   text,
  internal_note   text,
  locale          text not null default 'ar',
  invoice_number  text unique,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  check (total_dzd = subtotal_dzd - discount_dzd + delivery_fee_dzd),
  check (delivery_method <> 'home' or address_line is not null),
  check (delivery_method <> 'pickup' or pickup_point_id is not null)
);
create index on orders (user_id, created_at desc);
create index on orders (status, created_at desc);
create trigger orders_touch before update on orders for each row execute function touch_updated_at();

alter table inventory_movements
  add constraint inventory_movements_order_fk foreign key (order_id) references orders(id) on delete set null;

create table order_items (
  id            bigint generated always as identity primary key,
  order_id      uuid not null references orders(id) on delete cascade,
  product_id    uuid references products(id) on delete set null,
  sku           text not null,
  name          jsonb not null,             -- snapshot at purchase time
  unit_price_dzd numeric(12,2) not null,
  quantity      int not null check (quantity > 0),
  line_total_dzd numeric(12,2) not null,
  check (line_total_dzd = unit_price_dzd * quantity)
);
create index on order_items (order_id);
create index on order_items (product_id);

create table order_status_history (
  id         bigint generated always as identity primary key,
  order_id   uuid not null references orders(id) on delete cascade,
  status     order_status not null,
  note       text,
  changed_by uuid,
  created_at timestamptz not null default now()
);
create index on order_status_history (order_id, created_at);

create table return_requests (
  id          uuid primary key default gen_random_uuid(),
  order_id    uuid not null references orders(id) on delete cascade,
  items       jsonb not null,               -- [{order_item_id, quantity}]
  reason      text not null,
  status      return_status not null default 'requested',
  admin_note  text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create trigger return_requests_touch before update on return_requests for each row execute function touch_updated_at();

-- B2B quotations.
create table quote_requests (
  id             uuid primary key default gen_random_uuid(),
  quote_number   text not null unique default ('Q-' || to_char(now(), 'YYMM') || '-' || substr(md5(random()::text), 1, 6)),
  user_id        uuid references profiles(id) on delete set null,
  company_name   text not null,
  contact_name   text not null,
  email          text,
  phone          text not null,
  wilaya_code    smallint references wilayas(code),
  message        text,
  status         quote_status not null default 'new',
  quoted_total_dzd numeric(12,2),
  valid_until    date,
  admin_note     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create trigger quote_requests_touch before update on quote_requests for each row execute function touch_updated_at();

create table quote_request_items (
  id            bigint generated always as identity primary key,
  quote_id      uuid not null references quote_requests(id) on delete cascade,
  product_id    uuid references products(id) on delete set null,
  description   text,                       -- free text when the product is not in the catalog
  quantity      int not null check (quantity > 0),
  quoted_unit_price_dzd numeric(12,2),
  check (product_id is not null or description is not null)
);

create table reviews (
  id          uuid primary key default gen_random_uuid(),
  product_id  uuid not null references products(id) on delete cascade,
  user_id     uuid not null references profiles(id) on delete cascade,
  rating      smallint not null check (rating between 1 and 5),
  title       text,
  body        text,
  status      review_status not null default 'pending',
  verified_purchase boolean not null default false,
  created_at  timestamptz not null default now(),
  unique (product_id, user_id)
);

-- Marketing.
create table banners (
  id         uuid primary key default gen_random_uuid(),
  placement  text not null default 'home_hero',
  title      jsonb not null check (is_localized(title)),
  subtitle   jsonb check (subtitle is null or is_localized(subtitle)),
  cta_label  jsonb check (cta_label is null or is_localized(cta_label)),
  cta_href   text,
  image_path text not null,
  sort_order int not null default 0,
  starts_at  timestamptz,
  ends_at    timestamptz,
  is_active  boolean not null default true
);

create table collections (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique,
  title       jsonb not null check (is_localized(title)),
  description jsonb check (description is null or is_localized(description)),
  image_path  text,
  show_on_home boolean not null default false,
  sort_order  int not null default 0,
  is_active   boolean not null default true
);

create table collection_products (
  collection_id uuid not null references collections(id) on delete cascade,
  product_id    uuid not null references products(id) on delete cascade,
  position      int not null default 0,
  primary key (collection_id, product_id)
);

-- Store-wide settings, e.g. {"reviews_enabled": false}.
create table settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);

-- ===== supabase/migrations/20261023000006_functions.sql =====
-- Business logic that must run on the server: authorisation helpers, order placement
-- (prices, stock and promotions are always recomputed here, never trusted from the client),
-- order status workflow, stock adjustments, search and analytics.

-- ---------------------------------------------------------------------------
-- Authorisation helpers
-- ---------------------------------------------------------------------------
create or replace function current_role_name() returns user_role
language sql stable security definer set search_path = public, extensions as $$
  select coalesce((select role from profiles where id = auth.uid()), 'customer'::user_role)
$$;

create or replace function is_staff() returns boolean
language sql stable security definer set search_path = public, extensions as $$
  select exists (select 1 from profiles where id = auth.uid() and role in ('staff', 'admin'))
$$;

create or replace function is_admin() returns boolean
language sql stable security definer set search_path = public, extensions as $$
  select exists (select 1 from profiles where id = auth.uid() and role = 'admin')
$$;

create or replace function is_approved_business(p_user uuid) returns boolean
language sql stable security definer set search_path = public, extensions as $$
  select p_user is not null and exists (
    select 1 from business_accounts where profile_id = p_user and status = 'approved')
$$;

-- ---------------------------------------------------------------------------
-- Pricing
-- ---------------------------------------------------------------------------
-- Unit price for a quantity, applying the best configured volume tier.
create or replace function unit_price(p_product uuid, p_quantity int, p_user uuid default auth.uid())
returns numeric
language sql stable security definer set search_path = public, extensions as $$
  select least(
    p.price_dzd,
    (select min(t.price_dzd) from price_tiers t
      where t.product_id = p.id and t.min_quantity <= p_quantity
        and (not t.business_only or is_approved_business(p_user))))
  from products p where p.id = p_product
$$;

-- ---------------------------------------------------------------------------
-- Inventory
-- ---------------------------------------------------------------------------
create or replace function apply_stock_change(
  p_product uuid, p_delta int, p_reason stock_reason, p_order uuid default null, p_note text default null)
returns int
language plpgsql security definer set search_path = public, extensions as $$
declare
  new_qty int;
begin
  update inventory set quantity = quantity + p_delta
   where product_id = p_product
   returning quantity into new_qty;
  if new_qty is null then
    raise exception 'unknown_product' using errcode = 'P0002';
  end if;
  insert into inventory_movements (product_id, delta, quantity_after, reason, order_id, note, created_by)
  values (p_product, p_delta, new_qty, p_reason, p_order, p_note, auth.uid());
  return new_qty;
exception when check_violation then
  raise exception 'insufficient_stock' using errcode = 'P0001';
end $$;
revoke all on function apply_stock_change(uuid, int, stock_reason, uuid, text) from public, anon, authenticated;

-- Staff stock adjustment from the admin dashboard.
create or replace function adjust_stock(p_product uuid, p_delta int, p_reason stock_reason, p_note text default null)
returns int
language plpgsql security definer set search_path = public, extensions as $$
begin
  if not is_staff() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_reason in ('sale', 'cancellation') then
    raise exception 'reason_reserved_for_orders' using errcode = '22023';
  end if;
  return apply_stock_change(p_product, p_delta, p_reason, null, p_note);
end $$;

-- ---------------------------------------------------------------------------
-- Order placement
-- ---------------------------------------------------------------------------
-- p_items:    [{"product_id": "...", "quantity": 2}, ...]
-- p_customer: {"name": "...", "phone": "...", "email": "...", "company": "..."}
-- p_delivery: {"method": "home"|"pickup", "wilaya_code": 19, "commune_id": 123,
--              "address_line": "...", "pickup_point_id": "..."}
-- Returns {"order_id", "order_number", "total_dzd", "guest_token"}.
create or replace function place_order(
  p_items jsonb, p_customer jsonb, p_delivery jsonb,
  p_promo_code text default null, p_note text default null, p_locale text default 'ar')
returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_user     uuid := auth.uid();
  v_guest    uuid := case when auth.uid() is null then gen_random_uuid() end;
  v_phone    text := normalize_dz_phone(p_customer->>'phone');
  v_name     text := nullif(btrim(p_customer->>'name'), '');
  v_method   delivery_method := (p_delivery->>'method')::delivery_method;
  v_wilaya   smallint := (p_delivery->>'wilaya_code')::smallint;
  v_commune  int := nullif(p_delivery->>'commune_id', '')::int;
  v_address  text := nullif(btrim(p_delivery->>'address_line'), '');
  v_pickup   uuid := nullif(p_delivery->>'pickup_point_id', '')::uuid;
  v_rate     delivery_rates%rowtype;
  v_promo    promo_codes%rowtype;
  v_subtotal numeric(12,2) := 0;
  v_discount numeric(12,2) := 0;
  v_fee      numeric(12,2);
  v_order    uuid;
  v_number   text;
  r          record;
  v_price    numeric(12,2);
  v_count    int;
  v_distinct int;
begin
  -- Customer validation
  if v_name is null or length(v_name) > 120 then
    raise exception 'invalid_name' using errcode = '22023';
  end if;
  if v_phone is null then
    raise exception 'invalid_phone' using errcode = '22023';
  end if;
  if p_locale not in ('ar', 'fr', 'en') then
    p_locale := 'ar';
  end if;

  -- Items validation
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'empty_cart' using errcode = '22023';
  end if;
  if jsonb_array_length(p_items) > 100 then
    raise exception 'too_many_items' using errcode = '22023';
  end if;
  select count(*), count(distinct (e->>'product_id')) into v_count, v_distinct
    from jsonb_array_elements(p_items) e;
  if v_count <> v_distinct then
    raise exception 'duplicate_items' using errcode = '22023';
  end if;

  -- Delivery validation
  select * into v_rate from delivery_rates dr
   join wilayas w on w.code = dr.wilaya_code and w.is_active
   where dr.wilaya_code = v_wilaya and dr.method = v_method and dr.is_active;
  if not found then
    raise exception 'delivery_unavailable' using errcode = '22023';
  end if;
  if v_commune is not null and not exists (
      select 1 from communes where id = v_commune and wilaya_code = v_wilaya and is_active) then
    raise exception 'invalid_commune' using errcode = '22023';
  end if;
  if v_method = 'home' then
    if v_address is null then
      raise exception 'address_required' using errcode = '22023';
    end if;
    v_pickup := null;
  else
    if not exists (select 1 from pickup_points where id = v_pickup and wilaya_code = v_wilaya and is_active) then
      raise exception 'invalid_pickup_point' using errcode = '22023';
    end if;
  end if;

  -- Lock stock rows in a stable order to avoid deadlocks, then price every line.
  if to_regclass('pg_temp._lines') is not null then
    drop table pg_temp._lines;
  end if;
  create temporary table _lines (
    product_id uuid primary key, sku text, name jsonb, quantity int, unit_price numeric(12,2)
  ) on commit drop;

  for r in
    select (e->>'product_id')::uuid as product_id, (e->>'quantity')::int as quantity
      from jsonb_array_elements(p_items) e
     order by 1
  loop
    if r.quantity is null or r.quantity < 1 or r.quantity > 999 then
      raise exception 'invalid_quantity' using errcode = '22023';
    end if;
    perform 1 from inventory i where i.product_id = r.product_id for update;
    insert into _lines
    select p.id, p.sku, p.name, r.quantity, unit_price(p.id, r.quantity, v_user)
      from products p
      join inventory i on i.product_id = p.id
     where p.id = r.product_id and p.status = 'active' and p.price_dzd is not null;
    if not found then
      raise exception 'product_unavailable' using errcode = '22023', detail = r.product_id::text;
    end if;
    if (select quantity from inventory where product_id = r.product_id) < r.quantity then
      raise exception 'insufficient_stock' using errcode = 'P0001',
        detail = (select sku from products where id = r.product_id);
    end if;
  end loop;

  select sum(unit_price * quantity) into v_subtotal from _lines;

  -- Delivery fee
  v_fee := case when v_rate.free_over_dzd is not null and v_subtotal >= v_rate.free_over_dzd
                then 0 else v_rate.fee_dzd end;

  -- Promotion
  if nullif(btrim(p_promo_code), '') is not null then
    select * into v_promo from promo_codes
     where code = btrim(p_promo_code)::extensions.citext and is_active
       and (starts_at is null or starts_at <= now())
       and (ends_at is null or ends_at > now())
     for update;
    if not found or (v_promo.max_uses is not null and v_promo.used_count >= v_promo.max_uses) then
      raise exception 'invalid_promo_code' using errcode = '22023';
    end if;
    if v_subtotal < v_promo.min_subtotal_dzd then
      raise exception 'promo_minimum_not_met' using errcode = '22023';
    end if;
    if v_promo.per_customer_limit is not null and (
        select count(*) from orders o
         where o.promo_code_id = v_promo.id and o.status not in ('cancelled')
           and (o.customer_phone = v_phone or (v_user is not null and o.user_id = v_user))
       ) >= v_promo.per_customer_limit then
      raise exception 'promo_limit_reached' using errcode = '22023';
    end if;
    v_discount := case v_promo.kind
      when 'percent' then round(v_subtotal * v_promo.value / 100, 2)
      when 'fixed' then least(v_promo.value, v_subtotal)
      else 0 end;
    if v_promo.kind = 'free_shipping' then
      v_fee := 0;
    end if;
    update promo_codes set used_count = used_count + 1 where id = v_promo.id;
  end if;

  insert into orders (
    user_id, guest_token, customer_name, customer_phone, customer_email, company_name,
    delivery_method, wilaya_code, commune_id, address_line, pickup_point_id,
    subtotal_dzd, discount_dzd, delivery_fee_dzd, total_dzd, promo_code_id, customer_note, locale)
  values (
    v_user, v_guest, v_name, v_phone, nullif(btrim(p_customer->>'email'), ''),
    nullif(btrim(p_customer->>'company'), ''),
    v_method, v_wilaya, v_commune, case when v_method = 'home' then v_address end, v_pickup,
    v_subtotal, v_discount, v_fee, v_subtotal - v_discount + v_fee, v_promo.id,
    left(nullif(btrim(p_note), ''), 1000), p_locale)
  returning id, order_number into v_order, v_number;

  insert into order_items (order_id, product_id, sku, name, unit_price_dzd, quantity, line_total_dzd)
  select v_order, product_id, sku, name, unit_price, quantity, unit_price * quantity from _lines;

  for r in select product_id, quantity from _lines loop
    perform apply_stock_change(r.product_id, -r.quantity, 'sale', v_order, null);
  end loop;

  insert into order_status_history (order_id, status, changed_by) values (v_order, 'pending', v_user);

  -- Empty the signed-in customer's cart (guest carts are cleared by the server action).
  if v_user is not null then
    delete from cart_items ci using carts c where c.id = ci.cart_id and c.user_id = v_user;
  end if;

  return jsonb_build_object(
    'order_id', v_order, 'order_number', v_number,
    'total_dzd', v_subtotal - v_discount + v_fee, 'guest_token', v_guest);
end $$;

-- ---------------------------------------------------------------------------
-- Order status workflow
-- ---------------------------------------------------------------------------
create or replace function order_transition_allowed(p_from order_status, p_to order_status) returns boolean
language sql immutable as $$
  select (p_from, p_to) in (
    ('pending', 'confirmed'), ('pending', 'cancelled'),
    ('confirmed', 'processing'), ('confirmed', 'cancelled'),
    ('processing', 'shipped'), ('processing', 'cancelled'),
    ('shipped', 'delivered'), ('shipped', 'returned'),
    ('delivered', 'returned'))
$$;

create or replace function set_order_status(p_order uuid, p_status order_status, p_note text default null)
returns order_status
language plpgsql security definer set search_path = public, extensions as $$
declare
  o orders%rowtype;
  r record;
begin
  select * into o from orders where id = p_order for update;
  if not found then
    raise exception 'order_not_found' using errcode = 'P0002';
  end if;

  -- Customers may only cancel their own order while it is still pending.
  if not is_staff() then
    if not (o.user_id = auth.uid() and o.status = 'pending' and p_status = 'cancelled') then
      raise exception 'forbidden' using errcode = '42501';
    end if;
  end if;

  if not order_transition_allowed(o.status, p_status) then
    raise exception 'invalid_transition' using errcode = '22023', detail = o.status || ' -> ' || p_status;
  end if;

  update orders set
    status = p_status,
    payment_status = case when p_status = 'delivered' and payment_method = 'cash_on_delivery'
                          then 'paid' else payment_status end,
    invoice_number = case when p_status = 'confirmed' and invoice_number is null
                          then 'F-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('invoice_number_seq')::text, 6, '0')
                          else invoice_number end
  where id = p_order;

  -- Cancelling puts the goods back on the shelf and frees the promo use.
  if p_status = 'cancelled' then
    for r in select product_id, quantity from order_items where order_id = p_order and product_id is not null loop
      perform apply_stock_change(r.product_id, r.quantity, 'cancellation', p_order, null);
    end loop;
    if o.promo_code_id is not null then
      update promo_codes set used_count = greatest(used_count - 1, 0) where id = o.promo_code_id;
    end if;
  end if;
  -- Returned goods are NOT restocked automatically: staff inspect them and use adjust_stock().

  insert into order_status_history (order_id, status, note, changed_by)
  values (p_order, p_status, p_note, auth.uid());
  return p_status;
end $$;

-- Guest order lookup (order number + phone, or the guest token kept in a cookie).
create or replace function find_guest_order(p_order_number text, p_phone text)
returns table (order_number text, status order_status, total_dzd numeric, created_at timestamptz, history jsonb)
language sql stable security definer set search_path = public, extensions as $$
  select o.order_number, o.status, o.total_dzd, o.created_at,
         (select jsonb_agg(jsonb_build_object('status', h.status, 'at', h.created_at) order by h.created_at)
            from order_status_history h where h.order_id = o.id)
    from orders o
   where o.order_number = upper(btrim(p_order_number))
     and o.customer_phone = normalize_dz_phone(p_phone)
$$;

-- ---------------------------------------------------------------------------
-- Search
-- ---------------------------------------------------------------------------
create or replace function category_tree(p_slug text) returns setof uuid
language sql stable set search_path = public as $$
  with recursive t as (
    select id from categories where slug = p_slug and is_active
    union all
    select c.id from categories c join t on c.parent_id = t.id where c.is_active
  ) select id from t
$$;

create or replace function search_products(
  p_query      text default null,
  p_category   text default null,
  p_brands     text[] default null,
  p_types      product_type[] default null,
  p_colors     ink_color[] default null,
  p_origin     product_origin default null,
  p_min_price  numeric default null,
  p_max_price  numeric default null,
  p_in_stock   boolean default false,
  p_printer    uuid default null,
  p_sort       text default 'relevance',   -- relevance | popular | newest | price_asc | price_desc
  p_limit      int default 24,
  p_offset     int default 0)
returns table (
  id uuid, slug text, sku text, name jsonb, model_code text, product_type product_type,
  origin product_origin, color ink_color, yield_type yield_type, page_yield int, volume_ml numeric,
  price_dzd numeric, compare_at_dzd numeric, brand_name text, brand_slug text, image_path text,
  in_stock boolean, low_stock boolean, rank real, total_count bigint)
language plpgsql stable set search_path = public, extensions as $$
#variable_conflict use_column
declare
  qn text := nullif(search_normalize(btrim(p_query)), '');
  qc text := code_normalize(p_query);
  tsq tsquery;
begin
  if qn is not null then
    tsq := websearch_to_tsquery('simple', qn);
  end if;
  p_limit := least(greatest(coalesce(p_limit, 24), 1), 100);
  p_offset := greatest(coalesce(p_offset, 0), 0);

  return query
  with printer_hits as (
    -- Searching a printer model returns its verified supplies.
    select distinct pc.product_id
      from printers pr join product_compatibility pc on pc.printer_id = pr.id and pc.verified
     where qn is not null and length(qc) >= 3 and pr.is_active and pr.model_norm like '%' || qc || '%'
  ),
  sales as (
    select oi.product_id, sum(oi.quantity) as sold
      from order_items oi join orders o on o.id = oi.order_id
     where o.status not in ('cancelled') and o.created_at > now() - interval '90 days'
     group by oi.product_id
  ),
  base as (
    select p.*, b.name as b_name, b.slug as b_slug, i.quantity as stock, i.low_stock_threshold,
           case when qn is null then 0::real else (
               coalesce(ts_rank(p.search_vector, tsq), 0)
             + case when length(qc) >= 3 and p.code_text like '%' || qc || '%' then 1.5 else 0 end
             + case when p.id in (select product_id from printer_hits) then 1.0 else 0 end
             + word_similarity(qn, p.search_text))::real end as score,
           coalesce(s.sold, 0) as sold
      from products p
      left join brands b on b.id = p.brand_id
      join inventory i on i.product_id = p.id
      left join sales s on s.product_id = p.id
     where p.status = 'active'
       and (qn is null
            or p.search_vector @@ tsq
            or (length(qc) >= 3 and p.code_text like '%' || qc || '%')
            or p.id in (select product_id from printer_hits)
            or word_similarity(qn, p.search_text) >= 0.5)
       and (p_category is null or p.category_id in (select category_tree(p_category)))
       and (p_brands is null or b.slug = any (p_brands))
       and (p_types is null or p.product_type = any (p_types))
       and (p_colors is null or p.color = any (p_colors))
       and (p_origin is null or p.origin = p_origin)
       and (p_min_price is null or p.price_dzd >= p_min_price)
       and (p_max_price is null or p.price_dzd <= p_max_price)
       and (not coalesce(p_in_stock, false) or i.quantity > 0)
       and (p_printer is null or exists (
             select 1 from product_compatibility pc
              where pc.product_id = p.id and pc.printer_id = p_printer and pc.verified))
  )
  select b.id, b.slug, b.sku, b.name, b.model_code, b.product_type, b.origin, b.color, b.yield_type,
         b.page_yield, b.volume_ml, b.price_dzd, b.compare_at_dzd, b.b_name, b.b_slug,
         (select pi.storage_path from product_images pi where pi.product_id = b.id order by pi.position limit 1),
         b.stock > 0, b.stock > 0 and b.stock <= b.low_stock_threshold, b.score,
         count(*) over ()
    from base b
   order by
     case when p_sort = 'price_asc' then b.price_dzd end asc nulls last,
     case when p_sort = 'price_desc' then b.price_dzd end desc nulls last,
     case when p_sort = 'newest' then b.published_at end desc nulls last,
     case when p_sort = 'popular' then b.sold end desc,
     case when p_sort = 'relevance' then b.score end desc,
     b.is_featured desc, b.sold desc, b.published_at desc nulls last, b.id
   limit p_limit offset p_offset;
end $$;

-- Autocomplete: a few products, printer models and categories for the search box.
create or replace function search_suggestions(p_query text, p_limit int default 6)
returns jsonb
language plpgsql stable set search_path = public, extensions as $$
declare
  qn text := search_normalize(btrim(p_query));
  qc text := code_normalize(p_query);
begin
  if length(qn) < 2 then
    return jsonb_build_object('products', '[]'::jsonb, 'printers', '[]'::jsonb, 'categories', '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'products', coalesce((
      select jsonb_agg(jsonb_build_object('slug', s.slug, 'name', s.name, 'model_code', s.model_code,
                                          'price_dzd', s.price_dzd, 'image_path', s.image_path))
        from search_products(p_query => p_query, p_limit => p_limit) s), '[]'::jsonb),
    'printers', coalesce((
      select jsonb_agg(x) from (
        select jsonb_build_object('id', pr.id, 'slug', pr.slug, 'model', pr.model, 'brand', b.name) as x
          from printers pr join brands b on b.id = pr.brand_id
         where pr.is_active and (pr.model_norm like '%' || qc || '%'
                                 or word_similarity(qn, search_normalize(b.name || ' ' || pr.model)) >= 0.5)
         order by similarity(pr.model_norm, qc) desc, pr.model
         limit p_limit) t), '[]'::jsonb),
    'categories', coalesce((
      select jsonb_agg(x) from (
        select jsonb_build_object('slug', c.slug, 'name', c.name) as x
          from categories c
         where c.is_active and word_similarity(qn, search_normalize(concat_ws(' ', c.name->>'ar', c.name->>'fr', c.name->>'en'))) >= 0.5
         limit 3) t), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------------
-- Admin analytics (real data only; empty until orders exist)
-- ---------------------------------------------------------------------------
create or replace view admin_daily_sales with (security_invoker = true) as
select date_trunc('day', o.created_at at time zone 'Africa/Algiers')::date as day,
       count(*) as orders,
       count(*) filter (where o.status = 'cancelled') as cancelled,
       sum(o.total_dzd) filter (where o.status not in ('cancelled', 'returned')) as revenue_dzd
  from orders o
 where is_staff()
 group by 1;

create or replace view admin_best_sellers with (security_invoker = true) as
select oi.product_id, oi.sku, max(oi.name::text)::jsonb as name,
       sum(oi.quantity) as units, sum(oi.line_total_dzd) as revenue_dzd
  from order_items oi join orders o on o.id = oi.order_id
 where is_staff() and o.status not in ('cancelled', 'returned')
 group by oi.product_id, oi.sku;

create or replace view admin_stock_alerts with (security_invoker = true) as
select p.id as product_id, p.sku, p.name, p.status, i.quantity, i.low_stock_threshold,
       case when i.quantity = 0 then 'out_of_stock' else 'low_stock' end as alert
  from products p join inventory i on i.product_id = p.id
 where is_staff() and p.status <> 'archived' and i.quantity <= i.low_stock_threshold;

-- ===== supabase/migrations/20261023000007_security.sql =====
-- Row Level Security. Principles:
--  * anon/authenticated can read only what a shopper should see (active, verified, own data).
--  * Orders and quotations are created only through SECURITY DEFINER functions that
--    validate everything server-side; there is no direct INSERT grant.
--  * Staff manage the catalog and orders; only admins change roles and settings.
--  * The service role (used only in server code) bypasses RLS, e.g. for guest carts.

-- Search runs with definer rights so it can use stock and sales without exposing them.
alter function search_products(text, text, text[], product_type[], ink_color[], product_origin,
  numeric, numeric, boolean, uuid, text, int, int) security definer;
alter function search_suggestions(text, int) security definer;

-- Enable RLS on every table in public.
do $$
declare t record;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Catalog (public read, staff write)
-- ---------------------------------------------------------------------------
create policy "public read" on categories for select using (is_active or is_staff());
create policy "public read" on brands for select using (is_active or is_staff());
create policy "public read" on product_groups for select using (true);
create policy "public read" on products for select using (status = 'active' or is_staff());
create policy "public read" on product_images for select
  using (exists (select 1 from products p where p.id = product_id and (p.status = 'active' or is_staff())));
create policy "public read" on price_tiers for select
  using (exists (select 1 from products p where p.id = product_id and (p.status = 'active' or is_staff())));
create policy "public read" on printer_series for select using (is_active or is_staff());
create policy "public read" on printers for select using (is_active or is_staff());
create policy "public read verified" on product_compatibility for select using (verified or is_staff());
create policy "public read" on banners for select
  using ((is_active and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now())) or is_staff());
create policy "public read" on collections for select using (is_active or is_staff());
create policy "public read" on collection_products for select using (true);
create policy "public read" on settings for select using (true);
create policy "public read" on wilayas for select using (is_active or is_staff());
create policy "public read" on communes for select using (is_active or is_staff());
create policy "public read" on pickup_points for select using (is_active or is_staff());
create policy "public read" on delivery_rates for select using (is_active or is_staff());

create policy "staff write" on categories for all using (is_staff()) with check (is_staff());
create policy "staff write" on brands for all using (is_staff()) with check (is_staff());
create policy "staff write" on product_groups for all using (is_staff()) with check (is_staff());
create policy "staff write" on products for all using (is_staff()) with check (is_staff());
create policy "staff write" on product_images for all using (is_staff()) with check (is_staff());
create policy "staff write" on price_tiers for all using (is_staff()) with check (is_staff());
create policy "staff write" on printer_series for all using (is_staff()) with check (is_staff());
create policy "staff write" on printers for all using (is_staff()) with check (is_staff());
create policy "staff write" on product_compatibility for all using (is_staff()) with check (is_staff());
create policy "staff write" on banners for all using (is_staff()) with check (is_staff());
create policy "staff write" on collections for all using (is_staff()) with check (is_staff());
create policy "staff write" on collection_products for all using (is_staff()) with check (is_staff());
create policy "staff write" on pickup_points for all using (is_staff()) with check (is_staff());
create policy "staff write" on delivery_rates for all using (is_staff()) with check (is_staff());
create policy "staff write" on communes for all using (is_staff()) with check (is_staff());
create policy "admin write" on wilayas for all using (is_admin()) with check (is_admin());
create policy "admin write" on settings for all using (is_admin()) with check (is_admin());

-- Stock is internal; shoppers see availability through product_availability().
create policy "staff only" on inventory for all using (is_staff()) with check (is_staff());
create policy "staff read" on inventory_movements for select using (is_staff());
create policy "staff only" on promo_codes for all using (is_staff()) with check (is_staff());

-- ---------------------------------------------------------------------------
-- Customers
-- ---------------------------------------------------------------------------
create policy "own profile" on profiles for select using (id = auth.uid() or is_staff());
create policy "own profile update" on profiles for update using (id = auth.uid()) with check (id = auth.uid());
-- Customers may only change these columns (never their role).
revoke update on profiles from anon, authenticated;
grant update (full_name, phone, locale) on profiles to authenticated;

create policy "own business" on business_accounts for select using (profile_id = auth.uid() or is_staff());
create policy "own business insert" on business_accounts for insert with check (profile_id = auth.uid());
create policy "staff review" on business_accounts for update using (is_staff()) with check (is_staff());
revoke insert, update on business_accounts from anon, authenticated;
grant insert (profile_id, company_name, activity, nif, nis, rc, article_imposition, billing_address)
  on business_accounts to authenticated;
grant update (status, reviewed_by, reviewed_at, company_name, activity, nif, nis, rc, article_imposition, billing_address)
  on business_accounts to authenticated;  -- the policy limits updates to staff

create policy "own addresses" on addresses for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own cart" on carts for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own cart items" on cart_items for all
  using (exists (select 1 from carts c where c.id = cart_id and c.user_id = auth.uid()))
  with check (exists (select 1 from carts c where c.id = cart_id and c.user_id = auth.uid()));
create policy "own wishlist" on wishlist_items for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Orders (created only by place_order)
-- ---------------------------------------------------------------------------
create policy "own orders" on orders for select using (user_id = auth.uid() or is_staff());
create policy "staff update" on orders for update using (is_staff()) with check (is_staff());
revoke insert, delete on orders from anon, authenticated;
revoke update on orders from anon, authenticated;
grant update (internal_note) on orders to authenticated;  -- staff policy applies; status changes use set_order_status()

create policy "own order items" on order_items for select
  using (exists (select 1 from orders o where o.id = order_id and (o.user_id = auth.uid() or is_staff())));
create policy "own order history" on order_status_history for select
  using (exists (select 1 from orders o where o.id = order_id and (o.user_id = auth.uid() or is_staff())));
revoke insert, update, delete on order_items, order_status_history from anon, authenticated;

create policy "own returns" on return_requests for select
  using (exists (select 1 from orders o where o.id = order_id and (o.user_id = auth.uid() or is_staff())));
create policy "request return" on return_requests for insert
  with check (exists (select 1 from orders o where o.id = order_id and o.user_id = auth.uid() and o.status = 'delivered'));
create policy "staff returns" on return_requests for update using (is_staff()) with check (is_staff());
revoke insert, update on return_requests from anon, authenticated;
grant insert (order_id, items, reason) on return_requests to authenticated;
grant update (status, admin_note) on return_requests to authenticated;  -- staff policy applies

-- Quotations: created through submit_quote(); readable by owner and staff.
create policy "own quotes" on quote_requests for select using (user_id = auth.uid() or is_staff());
create policy "staff quotes" on quote_requests for update using (is_staff()) with check (is_staff());
create policy "own quote items" on quote_request_items for select
  using (exists (select 1 from quote_requests q where q.id = quote_id and (q.user_id = auth.uid() or is_staff())));
create policy "staff quote items" on quote_request_items for update using (is_staff()) with check (is_staff());
revoke insert, delete on quote_requests, quote_request_items from anon, authenticated;

-- Reviews: shown once approved and only while reviews are enabled.
create policy "public approved" on reviews for select
  using ((status = 'approved' and coalesce((select (value)::boolean from settings where key = 'reviews_enabled'), false))
         or user_id = auth.uid() or is_staff());
create policy "write own review" on reviews for insert with check (user_id = auth.uid());
create policy "staff moderate" on reviews for update using (is_staff()) with check (is_staff());
create policy "staff delete" on reviews for delete using (is_staff() or user_id = auth.uid());
revoke insert, update on reviews from anon, authenticated;
grant insert (product_id, user_id, rating, title, body) on reviews to authenticated;
grant update (status) on reviews to authenticated;  -- staff policy applies

-- ---------------------------------------------------------------------------
-- Secure entry points
-- ---------------------------------------------------------------------------

-- Public stock status without exposing exact quantities.
create or replace function product_availability(p_ids uuid[])
returns table (product_id uuid, in_stock boolean, low_stock boolean)
language sql stable security definer set search_path = public, extensions as $$
  select i.product_id, i.quantity > 0, i.quantity > 0 and i.quantity <= i.low_stock_threshold
    from inventory i join products p on p.id = i.product_id and p.status = 'active'
   where i.product_id = any (p_ids)
$$;

-- B2B quotation request (works for guests and signed-in customers).
-- p_quote: {"company_name","contact_name","email","phone","wilaya_code","message"}
-- p_items: [{"product_id": "..."} or {"description": "..."}, "quantity": n]
create or replace function submit_quote(p_quote jsonb, p_items jsonb)
returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_id uuid;
  v_number text;
  v_phone text := normalize_dz_phone(p_quote->>'phone');
begin
  if nullif(btrim(p_quote->>'company_name'), '') is null or nullif(btrim(p_quote->>'contact_name'), '') is null then
    raise exception 'company_and_contact_required' using errcode = '22023';
  end if;
  if v_phone is null then
    raise exception 'invalid_phone' using errcode = '22023';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 200 then
    raise exception 'invalid_items' using errcode = '22023';
  end if;
  insert into quote_requests (user_id, company_name, contact_name, email, phone, wilaya_code, message)
  values (auth.uid(), left(btrim(p_quote->>'company_name'), 200), left(btrim(p_quote->>'contact_name'), 120),
          nullif(btrim(p_quote->>'email'), ''), v_phone, nullif(p_quote->>'wilaya_code', '')::smallint,
          left(nullif(btrim(p_quote->>'message'), ''), 4000))
  returning id, quote_number into v_id, v_number;

  insert into quote_request_items (quote_id, product_id, description, quantity)
  select v_id,
         (select p.id from products p where p.id = nullif(e->>'product_id', '')::uuid and p.status = 'active'),
         left(nullif(btrim(e->>'description'), ''), 500),
         (e->>'quantity')::int
    from jsonb_array_elements(p_items) e;
  return jsonb_build_object('quote_id', v_id, 'quote_number', v_number);
exception
  when check_violation or not_null_violation or invalid_text_representation then
    raise exception 'invalid_items' using errcode = '22023';
end $$;

-- Role changes (admin only).
create or replace function set_user_role(p_user uuid, p_role user_role)
returns void
language plpgsql security definer set search_path = public, extensions as $$
begin
  if not is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_user = auth.uid() and p_role <> 'admin' then
    raise exception 'cannot_demote_self' using errcode = '22023';
  end if;
  update profiles set role = p_role where id = p_user;
end $$;

-- Execute permissions.
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function
  is_localized(jsonb), search_normalize(text), code_normalize(text), normalize_dz_phone(text),
  current_role_name(), is_staff(), is_admin(), unit_price(uuid, int, uuid),
  place_order(jsonb, jsonb, jsonb, text, text, text),
  set_order_status(uuid, order_status, text), find_guest_order(text, text),
  category_tree(text),
  search_products(text, text, text[], product_type[], ink_color[], product_origin, numeric, numeric, boolean, uuid, text, int, int),
  search_suggestions(text, int), product_availability(uuid[]), submit_quote(jsonb, jsonb),
  order_transition_allowed(order_status, order_status), is_approved_business(uuid)
  to anon, authenticated;
grant execute on function adjust_stock(uuid, int, stock_reason, text), set_user_role(uuid, user_role)
  to authenticated;

